/** Shop preview generated by the ACTUAL in-game Canvas 2D workstation painter.
 * This renders a fixture of a real owned Linux PC, not a stock/concept image.
 */
import type {GameState} from "../sim/types.js";
import type {LinuxMachineId} from "../sim/linuxMachines.js";
import {drawRetroComputer} from "./retroComputer.js";

export function drawLinuxWorkstationPreview(ctx:CanvasRenderingContext2D,id:LinuxMachineId):void{
 const {width,height}=ctx.canvas;
 ctx.save();
 ctx.fillStyle="#e1e7dd";ctx.fillRect(0,0,width,height);
 // The draw call uses the same geometry, chassis and screen activity as the salon.
 // A minimal state is sufficient because the renderer only reads these fields.
 const state={
  totalMinutes:(360+210)*720,
  customers:[],pcTiers:[1],pcWear:[0],pcGpus:[null],pcLinuxModels:[id],
  pcOperatingSystems:["linux"],pcLinuxInstalled:[true],pcPoweredOff:[false]
 } as unknown as GameState;
 const camera={originX:width*.42,originY:height*.37,zoom:1.65};
 drawRetroComputer(ctx,camera,{x:0,y:0},0,0,true,state,false);
 ctx.restore();
}
